                if (!str[0]) break;

                if ((str[0] != '$') && (str[0] != '%') && (str[0] != '@')) {
                        gf_fprintf(dump, "%c", str[0]);
@@ -2128,228 +2129,273 @@ static void inspect_dump_mpeg124(PidCtx *pctx, char *data, u32 size, FILE *dump)
